(function(){
  'use strict';
  if(window.htmx){
    return;
  }
  const bound=new WeakSet();
  function ready(fn){
    if(document.readyState==='loading'){
      document.addEventListener('DOMContentLoaded',fn);
    }else{
      fn();
    }
  }
  function dispatch(el,name,detail){
    if(!el){
      return null;
    }
    const evt=new CustomEvent(name,{bubbles:true,cancelable:true,detail:detail||{}});
    el.dispatchEvent(evt);
    return evt;
  }
  function parseTriggers(attr,defaultEvent){
    if(!attr){
      return[{event:defaultEvent}];
    }
    const triggers=[];
    attr.split(',').forEach(part=>{
      const trimmed=part.trim();
      if(!trimmed){
        return;
      }
      const tokens=trimmed.split(/\s+/);
      const eventName=tokens.shift();
      if(!eventName){
        return;
      }
      const trig={event:eventName,source:null,once:false};
      tokens.forEach(token=>{
        if(token.startsWith('from:')){
          trig.source=token.slice(5);
        }else if(token==='once'){
          trig.once=true;
        }
      });
      triggers.push(trig);
    });
    return triggers.length?triggers:[{event:defaultEvent}];
  }
  function getSourceElements(selector,el){
    if(!selector||selector==='this'){
      return[el];
    }
    if(selector==='window'){
      return[window];
    }
    if(selector==='document'){
      return[document];
    }
    if(selector==='body'){
      return[document.body];
    }
    if(selector.startsWith('closest ')){
      const sel=selector.slice(8).trim();
      const found=el.closest(sel);
      return found?[found]:[];
    }
    try{
      return Array.from(document.querySelectorAll(selector));
    }catch(err){
      return[];
    }
  }
  function resolveTarget(el){
    const attr=el.getAttribute('hx-target');
    if(!attr||attr==='this'){
      return el;
    }
    if(attr==='body'){
      return document.body;
    }
    if(attr.startsWith('closest ')){
      const sel=attr.slice(8).trim();
      const found=el.closest(sel);
      if(found){
        return found;
      }
    }
    try{
      const target=document.querySelector(attr);
      if(target){
        return target;
      }
    }catch(err){
    }
    return el;
  }
  function applySwap(target,swap,html){
    if(!target){
      return;
    }
    if(swap==='outerhtml'){
      const parent=target.parentNode;
      if(!parent){
        return;
      }
      const temp=document.createElement('div');
      temp.innerHTML=html;
      const nodes=Array.from(temp.childNodes);
      nodes.forEach(node=>{
        parent.insertBefore(node,target);
      });
      parent.removeChild(target);
      nodes.forEach(node=>{
        if(node.nodeType===1){
          scan(node);
        }
      });
    }else{
      target.innerHTML=html;
      scan(target);
    }
  }
  function dispatchTriggers(raw){
    if(!raw){
      return;
    }
    const fire=(name,detail)=>{
      if(!name){
        return;
      }
      dispatch(document.body,name,detail);
    };
    try{
      const parsed=JSON.parse(raw);
      if(typeof parsed==='string'){
        fire(parsed,null);
      }else if(Array.isArray(parsed)){
        parsed.forEach(name=>fire(name,null));
      }else if(parsed&&typeof parsed==='object'){
        Object.keys(parsed).forEach(name=>fire(name,parsed[name]));
      }
    }catch(err){
      raw.split(',').forEach(name=>fire(name.trim(),null));
    }
  }
  function makeRequest(el,method,url,evtInfo){
    if(!url){
      return;
    }
    if(el.hasAttribute('disabled')){
      return;
    }
    const confirmMessage=el.getAttribute('hx-confirm');
    if(confirmMessage&&!window.confirm(confirmMessage)){
      return;
    }
    const target=resolveTarget(el);
    const swap=(el.getAttribute('hx-swap')||'innerHTML').toLowerCase();
    const headerValues={
      'HX-Request':'true',
      'X-Requested-With':'XMLHttpRequest',
      'HX-Trigger':el.id||'',
      'HX-Trigger-Name':el.getAttribute('name')||'',
      'HX-Target':target&&target.id?target.id:'',
      'HX-Current-URL':window.location.href
    };
    const configDetail={
      headers:headerValues,
      target:target,
      triggeringEvent:evtInfo&&evtInfo.event?evtInfo.event:null
    };
    dispatch(el,'htmx:configRequest',configDetail);
    const beforeEvent=dispatch(el,'htmx:beforeRequest',{
      target:target,
      headers:headerValues,
      triggeringEvent:evtInfo&&evtInfo.event?evtInfo.event:null
    });
    if(beforeEvent&&beforeEvent.defaultPrevented){
      return;
    }
    const headers=new Headers();
    Object.keys(headerValues).forEach(key=>{
      const value=headerValues[key];
      if(value!==undefined&&value!==null&&value!==''){
        headers.append(key,value);
      }
    });
    const options={
      method:method.toUpperCase(),
      headers:headers,
      credentials:'same-origin'
    };
    let requestUrl=url;
    if(options.method==='GET'){
      if(el.tagName==='FORM'){
        const formData=new FormData(el);
        const params=new URLSearchParams();
        formData.forEach((value,key)=>{
          if(typeof value==='string'){
            params.append(key,value);
          }
        });
        const qs=params.toString();
        if(qs){
          requestUrl+=requestUrl.indexOf('?')>=0?'&':'?'+qs;
        }
      }
    }else{
      if(el.tagName==='FORM'){
        options.body=new FormData(el);
      }else{
        options.body=new FormData();
      }
    }
    fetch(requestUrl,options).then(response=>{
      dispatch(el,'htmx:afterRequest',{target:target,response:response});
      const redirect=response.headers.get('HX-Redirect')||response.headers.get('HX-Location');
      if(redirect){
        window.location.href=redirect;
        return;
      }
      const refresh=response.headers.get('HX-Refresh');
      if(refresh&&refresh.toLowerCase()==='true'){
        window.location.reload();
        return;
      }
      const processText=text=>{
        if(!response.ok){
          if(target){
            target.innerHTML=text||'<div class="text-danger">Kunne ikke indlæse indhold.</div>';
          }
          return;
        }
        const beforeSwap=dispatch(el,'htmx:beforeSwap',{
          target:target,
          response:response,
          html:text
        });
        if(beforeSwap&&beforeSwap.defaultPrevented){
          return;
        }
        applySwap(target,swap,text);
        dispatch(el,'htmx:afterSwap',{target:target,response:response});
        dispatchTriggers(response.headers.get('HX-Trigger'));
        dispatchTriggers(response.headers.get('HX-Trigger-After-Swap'));
        dispatchTriggers(response.headers.get('HX-Trigger-After-Settle'));
      };
      if(response.status===204){
        processText('');
        return;
      }
      return response.text().then(processText);
    }).catch(err=>{
      if(target){
        target.innerHTML='<div class="text-danger">Fejl under indlæsning.</div>';
      }
      console.error('htmx-lite error',err);
    });
  }
  function attachTrigger(el,trigger,callback){
    if(!trigger){
      return;
    }
    if(trigger.event==='load'){
      let executed=false;
      const loadFn=()=>{
        if(trigger.once&&executed){
          return;
        }
        executed=true;
        callback({event:null,trigger:'load'});
      };
      ready(loadFn);
      return;
    }
    const handler=ev=>{
      if(ev&&(trigger.event==='submit'||trigger.event==='click')){
        if(ev.preventDefault){
          ev.preventDefault();
        }
        if(trigger.event==='submit'&&ev.stopPropagation){
          ev.stopPropagation();
        }
      }
      callback({event:ev,trigger:trigger.event});
    };
    const sources=getSourceElements(trigger.source,el);
    const finalSources=sources&&sources.length?sources:[el];
    finalSources.forEach(source=>{
      if(source&&source.addEventListener){
        source.addEventListener(trigger.event,handler,{once:!!trigger.once});
      }
    });
  }
  function setupElement(el){
    if(bound.has(el)){
      return;
    }
    const getUrl=el.getAttribute('hx-get');
    const postUrl=el.getAttribute('hx-post');
    const method=postUrl?'post':getUrl?'get':null;
    const url=postUrl||getUrl;
    if(!method||!url){
      return;
    }
    bound.add(el);
    const defaultEvent=el.tagName==='FORM'?'submit':'click';
    const triggers=parseTriggers(el.getAttribute('hx-trigger'),defaultEvent);
    triggers.forEach(trigger=>attachTrigger(el,trigger,info=>makeRequest(el,method,url,info)));
    if(method==='post'&&el.tagName==='FORM'&&!el.getAttribute('hx-trigger')){
      el.addEventListener('submit',function(ev){
        ev.preventDefault();
        makeRequest(el,method,url,{event:ev,trigger:'submit'});
      });
    }
  }
  function scan(root){
    if(!root){
      return;
    }
    const elements=[];
    if(root.nodeType===1&&(root.hasAttribute('hx-get')||root.hasAttribute('hx-post'))){
      elements.push(root);
    }
    if(root.querySelectorAll){
      root.querySelectorAll('[hx-get],[hx-post]').forEach(el=>elements.push(el));
    }
    elements.forEach(el=>setupElement(el));
  }
  const api={
    version:'1.9.12-local',
    trigger:function(target,eventName,detail){
      if(!eventName){
        return;
      }
      let elements=[];
      if(typeof target==='string'){
        try{
          elements=Array.from(document.querySelectorAll(target));
        }catch(err){
          elements=[];
        }
      }else if(target instanceof Element||target===window||target===document){
        elements=[target];
      }else if(Array.isArray(target)){
        elements=target;
      }
      elements.forEach(el=>{
        if(!el){
          return;
        }
        const evt=new CustomEvent(eventName,{bubbles:true,detail:detail||{}});
        el.dispatchEvent(evt);
      });
    },
    onLoad:function(callback){
      ready(()=>callback(document.body));
    },
    _scan:scan
  };
  window.htmx=api;
  ready(()=>scan(document.body));
})();
